package emit

import (
	"bytes"
	"cmp"
	"fmt"
	"go/format"
	"path/filepath"
	"slices"
	"strconv"
	"strings"

	"github.com/AlexAli29/orm/internal/gen/model"
)

// Header marks every generated file. The convention is the one the Go tool
// itself recognises, so tooling that skips generated code skips these.
const Header = "// Code generated by orm. DO NOT EDIT."

// runtimeImport is the package generated code is written against.
const runtimeImport = "github.com/AlexAli29/orm"

// pgxImport is the driver, named by generated code for transaction options and
// for the connection type registration is taught through.
const pgxImport = "github.com/jackc/pgx/v5"

// Generated file names. They share a prefix so that a directory listing groups
// them, and an extension the Go tool and most tooling already treat as output.
const (
	tablesFile = "orm_tables.gen.go"
	metaFile   = "orm_meta.gen.go"
	relFile    = "orm_rel.gen.go"
	dbFile     = "orm_db.gen.go"
)

// GeneratedFiles are the names emit writes into a package. Callers that need to
// tell generated code from hand-written code — the collision check does — use
// this rather than guessing.
var GeneratedFiles = []string{tablesFile, metaFile, relFile, dbFile}

// IsGenerated reports whether a file name is one emit writes.
func IsGenerated(name string) bool { return slices.Contains(GeneratedFiles, filepath.Base(name)) }

// File is one rendered, formatted source file.
type File struct {
	// Path is where the file belongs.
	Path string
	// Content is formatted Go source.
	Content []byte
}

// Input is what generation needs. Everything in it was established by
// reconciliation; nothing here is discovered.
type Input struct {
	Mapping *model.Mapping
	// Reserved lists, per package path, the identifiers the author's own files
	// already declare. A generated name that collides with one of them is
	// reported rather than renamed.
	Reserved map[string][]string
}

// Generate renders every generated file for every package in the mapping.
//
// It renders all of them or none. A caller that wrote the first file and then
// discovered the second could not be generated would leave a package that no
// longer compiles, which is a worse state than the one it started in.
func Generate(in Input) ([]File, error) {
	if in.Mapping == nil || len(in.Mapping.Entities) == 0 {
		return nil, fmt.Errorf("nothing to generate: the mapping has no entities")
	}

	byPkg := make(map[string][]*model.EntityMapping)
	for _, em := range in.Mapping.Entities {
		byPkg[em.Entity.PkgPath] = append(byPkg[em.Entity.PkgPath], em)
	}
	pkgPaths := make([]string, 0, len(byPkg))
	for p := range byPkg {
		pkgPaths = append(pkgPaths, p)
	}
	slices.Sort(pkgPaths)

	var out []File
	for _, pkgPath := range pkgPaths {
		files, err := generatePackage(byPkg[pkgPath], in.Reserved[pkgPath])
		if err != nil {
			return nil, err
		}
		out = append(out, files...)
	}
	return out, nil
}

// pkgContext is one package's worth of generation.
type pkgContext struct {
	name string
	// path is the package's own import path, which a generated file in it must
	// never import.
	path     string
	dir      string
	entities []*model.EntityMapping
	// names maps each generated identifier to what produced it, so a collision
	// can name both sides.
	names map[string]string
}

func generatePackage(entities []*model.EntityMapping, reserved []string) ([]File, error) {
	slices.SortFunc(entities, func(a, b *model.EntityMapping) int {
		return cmp.Compare(a.Entity.Name, b.Entity.Name)
	})

	first := entities[0].Entity
	c := &pkgContext{
		name:     first.PkgName,
		path:     first.PkgPath,
		dir:      first.PkgDir,
		entities: entities,
		names:    make(map[string]string),
	}
	if c.dir == "" {
		return nil, fmt.Errorf("package %s has no directory to generate into", first.PkgPath)
	}
	for _, em := range entities {
		// Generated code goes into the entity's own package. Writing it
		// elsewhere means qualifying every entity type and re-deriving what is
		// in scope there — a feature, not a detail.
		//
		// The config still carries `output`, and it is validated, because that
		// is the door this goes through when it opens: generating a whole
		// entity graph into one directory is what would let a relation cross a
		// package boundary, since the generated code would then be on one side
		// of it. Refusing a value the config accepts keeps the field's meaning
		// fixed rather than inventing it later.
		if em.Entity.OutputDir != "" && em.Entity.OutputDir != em.Entity.PkgDir {
			return nil, fmt.Errorf("%s generates into %s, but generated code is written into the entity's own package; set output: same",
				em.Entity.Display(), em.Entity.OutputDir)
		}
	}
	if err := c.claimNames(reserved); err != nil {
		return nil, err
	}

	tables, err := c.tables()
	if err != nil {
		return nil, err
	}
	meta, err := c.meta()
	if err != nil {
		return nil, err
	}
	rels, err := c.relations()
	if err != nil {
		return nil, err
	}
	db, err := c.db()
	if err != nil {
		return nil, err
	}
	files := []File{tables, meta}
	// relations returns a zero File when the package declares none.
	if rels.Path != "" {
		files = append(files, rels)
	}
	return append(files, db), nil
}

// claimNames derives every identifier the package will gain and refuses if one
// of them is already taken or is not a legal identifier.
func (c *pkgContext) claimNames(reserved []string) error {
	taken := make(map[string]bool, len(reserved))
	for _, r := range reserved {
		taken[r] = true
	}

	claim := func(name, from, kind string) error {
		if err := validateIdentifier(name, from, kind); err != nil {
			return err
		}
		if taken[name] {
			return fmt.Errorf("generating %s for %s %q would redeclare %s, which package %s already declares",
				name, kind, from, name, c.name)
		}
		if other, ok := c.names[name]; ok {
			return fmt.Errorf("%s and %s both generate %s", other, from, name)
		}
		c.names[name] = from
		return nil
	}

	if err := claim(DBTypeName, c.name, "package"); err != nil {
		return err
	}
	if err := claim(DBCtorName, c.name, "package"); err != nil {
		return err
	}
	for _, em := range c.entities {
		entity, table := em.Entity.Name, em.Table.Name
		for _, n := range []struct{ name, from, kind string }{
			{exportedFromTable(table), table, "table"},
			{sourceVarName(table), table, "table"},
			{tableTypeName(entity), entity, "entity"},
			{tableCtorName(entity), entity, "entity"},
			{metaVarName(entity), entity, "entity"},
			{destFuncName(entity), entity, "entity"},
			{valueFuncName(entity), entity, "entity"},
		} {
			if err := claim(n.name, n.from, n.kind); err != nil {
				return err
			}
		}
	}
	return nil
}

// tables renders the descriptors a caller writes queries against.
func (c *pkgContext) tables() (File, error) {
	b := newBuilder(c.name, c.path)
	b.imports(runtimeImport)

	for _, em := range c.entities {
		entity := em.Entity.Name
		table := em.Table
		typeName := tableTypeName(entity)
		srcName := sourceVarName(table.Name)
		varName := exportedFromTable(table.Name)

		descs := make([]descriptor, len(em.Cols))
		for i, cm := range em.Cols {
			descs[i] = describeColumn(entity, cm)
			b.imports(descs[i].Imports...)
		}

		ctorName := tableCtorName(entity)

		b.line("// %s is the occurrence of %s that %s reads from.", srcName, table.Qualified(), varName)
		b.line("var %s = orm.NewSource(%s, %s)", srcName, quote(table.Schema), quote(table.Name))
		b.blank()

		if len(em.Rels) > 0 {
			b.line("// %s holds one typed descriptor per mapped column of %s, and one", typeName, table.Qualified())
			b.line("// per relation reconciliation proved.")
		} else {
			b.line("// %s holds one typed descriptor per mapped column of %s.", typeName, table.Qualified())
		}
		b.line("type %s struct {", typeName)
		b.line("\tsrc *orm.Source")
		for i, cm := range em.Cols {
			b.line("\t%s %s", cm.Field.Name, descs[i].Type)
		}
		for _, rel := range em.Rels {
			b.line("\t%s orm.Rel[%s, %s]", rel.Field.Name, entity, rel.Target.Entity.Name)
		}
		b.line("}")
		b.blank()

		// Every column is rebuilt from src, so an alias cannot end up with
		// some columns pointing at the original occurrence — the mistake that
		// would make scope validation quietly meaningless.
		b.line("// %s builds the descriptors for one occurrence of %s.", ctorName, table.Qualified())
		b.line("func %s(src *orm.Source) %s {", ctorName, typeName)
		b.line("\treturn %s{", typeName)
		b.line("\t\tsrc: src,")
		for i, cm := range em.Cols {
			args := quote(cm.Column.Name)
			for _, extra := range descs[i].Extra {
				args += ", " + quote(extra)
			}
			for _, raw := range descs[i].Raw {
				args += ", " + raw
			}
			b.line("\t\t%s: %s(src, %s),", cm.Field.Name, descs[i].Ctor, args)
		}
		for _, rel := range em.Rels {
			b.line("\t\t%s: %s,", rel.Field.Name, relDescriptor(entity, rel))
		}
		b.line("\t}")
		b.line("}")
		b.blank()

		b.line("// %s addresses the columns of %s.", varName, table.Qualified())
		b.line("var %s = %s(%s)", varName, ctorName, srcName)
		b.blank()

		b.line("// As returns descriptors for a second occurrence of %s under", table.Qualified())
		b.line("// alias, leaving %s untouched. Use it with QueryFrom, or to compare", varName)
		b.line("// one occurrence of the table against another.")
		b.line("func (t %s) As(alias string) %s { return %s(t.src.As(alias)) }", typeName, typeName, ctorName)
		b.blank()

		b.line("// Source returns the occurrence these descriptors qualify against.")
		b.line("func (t %s) Source() *orm.Source { return t.src }", typeName)
		b.blank()
	}
	return b.file(filepath.Join(c.dir, tablesFile))
}

// meta renders the entity metadata and the scanner it points at.
func (c *pkgContext) meta() (File, error) {
	b := newBuilder(c.name, c.path)
	b.imports(runtimeImport)

	for _, em := range c.entities {
		entity := em.Entity.Name
		table := em.Table
		metaName := metaVarName(entity)
		destName := destFuncName(entity)
		valueName := valueFuncName(entity)

		b.line("// %s describes how %s is read from %s.", metaName, entity, table.Qualified())
		b.line("var %s = orm.EntityMeta[%s]{", metaName, entity)
		b.line("\tTable: orm.TableID{Schema: %s, Name: %s},", quote(table.Schema), quote(table.Name))
		// The repository has to hold the same occurrence the descriptors were
		// built from, or every predicate over them is out of scope.
		b.line("\tSource: %s,", sourceVarName(table.Name))
		b.line("\tColumns: []orm.ColumnMeta{")
		for _, cm := range em.Cols {
			b.line("\t\t{Name: %s, Field: %s%s},", quote(cm.Column.Name), quote(cm.Field.Name), columnFlags(cm.Column))
		}
		b.line("\t},")
		b.line("\tDest:  %s,", destName)
		b.line("\tValue: %s,", valueName)
		b.line("}")
		b.blank()

		b.line("// %s returns a pointer to the field holding column idx of %s.", destName, table.Qualified())
		b.line("//")
		b.line("// The switch is over a constant index into the column list above, so")
		b.line("// scanning a row costs no reflection and no lookup by name.")
		b.line("func %s(e *%s, idx int) any {", destName, entity)
		b.line("\tswitch idx {")
		for i, cm := range em.Cols {
			b.line("\tcase %d:", i)
			b.line("\t\treturn &e.%s", cm.Field.Name)
		}
		b.line("\tdefault:")
		b.line("\t\treturn nil")
		b.line("\t}")
		b.line("}")
		b.blank()

		b.line("// %s returns the value of the field holding column idx of %s.", valueName, table.Qualified())
		b.line("//")
		b.line("// It is the counterpart of %s and is written the same way, so an", destName)
		b.line("// insert reads the entity without reflection either.")
		b.line("func %s(e *%s, idx int) any {", valueName, entity)
		b.line("\tswitch idx {")
		for i, cm := range em.Cols {
			b.line("\tcase %d:", i)
			b.line("\t\treturn e.%s", cm.Field.Name)
		}
		b.line("\tdefault:")
		b.line("\t\treturn nil")
		b.line("\t}")
		b.line("}")
		b.blank()
	}
	return b.file(filepath.Join(c.dir, metaFile))
}

// repoTypeFor names the runtime repository a relation kind gets.
//
// The capability is the type. A view reaches ViewRepo, which holds an ordinary
// repository privately and hands back only its query builder, so the write
// methods are absent rather than present-and-failing. A materialized view
// reaches MaterializedViewRepo, which is that plus Refresh — and an ordinary
// view does not get Refresh, because there is nothing stored to refresh.
func repoTypeFor(em *model.EntityMapping) string {
	switch em.Entity.Kind {
	case model.RelView:
		return "ViewRepo"
	case model.RelMaterializedView:
		return "MaterializedViewRepo"
	default:
		return "Repo"
	}
}

// repoCtorArgs renders the arguments the repository constructor takes.
//
// A materialized view's constructor takes one more: the name of the index that
// lets REFRESH CONCURRENTLY run, or the empty string when there is none. It is
// decided here, from the schema, rather than looked up at runtime — the
// question is answered by the relation's definition and cannot change without
// a migration, so asking the database every time would be asking something
// already known.
func repoCtorArgs(em *model.EntityMapping, metaVar string) string {
	args := "ex, &" + metaVar
	if em.Entity.Kind == model.RelMaterializedView {
		args += ", " + quote(em.ConcurrentRefreshIndex())
	}
	return args
}

// db renders the per-package handle that binds repositories to an executor.
func (c *pkgContext) db() (File, error) {
	b := newBuilder(c.name, c.path)
	b.imports(runtimeImport)

	b.line("// %s reads this package's entities through one executor.", DBTypeName)
	b.line("//")
	b.line("// The repositories are the runtime's generic ones: nothing about reading a")
	b.line("// row differs per entity, so nothing per entity is generated for it.")
	b.line("//")
	b.line("// A view gets a read-only repository. It has no Insert, Update, Delete or")
	b.line("// CopyFrom — not methods that fail, no methods — so writing through a view")
	b.line("// is a compile error at the line that tried rather than a runtime error on")
	b.line("// the path least likely to be tested.")
	b.line("type %s struct {", DBTypeName)
	b.line("\tex orm.Executor")
	for _, em := range c.entities {
		b.line("\t%s *orm.%s[%s]", exportedFromTable(em.Table.Name), repoTypeFor(em), em.Entity.Name)
	}
	b.line("}")
	b.blank()

	b.line("// %s binds the generated metadata to ex, which may be a *pgxpool.Pool, a", DBCtorName)
	b.line("// pgx.Tx or a *pgx.Conn.")
	b.line("func %s(ex orm.Executor) *%s {", DBCtorName, DBTypeName)
	b.line("\treturn &%s{", DBTypeName)
	b.line("\t\tex: ex,")
	for _, em := range c.entities {
		b.line("\t\t%s: orm.New%s(%s),", exportedFromTable(em.Table.Name),
			repoTypeFor(em), repoCtorArgs(em, metaVarName(em.Entity.Name)))
	}
	b.line("\t}")
	b.line("}")
	b.blank()

	b.line("// Executor returns the executor every repository here reads through.")
	b.line("//")
	b.line("// Inside a transaction callback that is the transaction, which is what lets")
	b.line("// code written against an executor rather than against %s take part in one.", DBTypeName)
	b.line("func (db *%s) Executor() orm.Executor { return db.ex }", DBTypeName)
	b.blank()

	b.line("// Tx runs fn inside a transaction.")
	b.line("//")
	b.line("// The %s handed to the callback is a new one bound to the transaction, so", DBTypeName)
	b.line("// every repository reached through it is in the transaction and the receiver's")
	b.line("// repositories are not:")
	b.line("//")
	// The example names this package's own first entity, because a generated
	// comment describing somebody else's types is a comment nobody can follow.
	first := c.entities[0]
	b.line("//\terr := db.Tx(ctx, func(tx *%s) error {", DBTypeName)
	b.line("//\t    %s, err := tx.%s.Insert(ctx, %s)",
		unexport(first.Entity.Name), exportedFromTable(first.Table.Name), unexport(first.Entity.Name))
	b.line("//\t    return err")
	b.line("//\t})")
	b.line("//")
	b.line("// Returning nil commits and returning an error rolls back. Calling it again on")
	b.line("// the transaction's own %s nests, which pgx implements with a savepoint.", DBTypeName)
	b.line("// Nothing is retried.")
	b.line("func (db *%s) Tx(ctx context.Context, fn func(*%s) error) error {", DBTypeName, DBTypeName)
	b.line("\treturn orm.RunTx(ctx, db.ex, func(ex orm.Executor) error { return fn(%s(ex)) })", DBCtorName)
	b.line("}")
	b.blank()

	b.line("// TxOptions runs fn inside a transaction with the given characteristics.")
	b.line("//")
	b.line("// Zero options mean the same as [%s.Tx]. Non-zero options inside a transaction", DBTypeName)
	b.line("// return orm.ErrNestedTxOptions, because PostgreSQL sets them for a transaction")
	b.line("// rather than for a savepoint inside one.")
	b.line("func (db *%s) TxOptions(ctx context.Context, opts pgx.TxOptions, fn func(*%s) error) error {", DBTypeName, DBTypeName)
	b.line("\treturn orm.RunTxOptions(ctx, db.ex, opts, func(ex orm.Executor) error { return fn(%s(ex)) })", DBCtorName)
	b.line("}")
	b.imports("context", pgxImport)

	c.registerTypes(b)
	return b.file(filepath.Join(c.dir, dbFile))
}

// registerTypes renders the connection hook for the PostgreSQL types pgx cannot
// know about until it is told.
//
// Enums, domains, composites and their array forms have OIDs assigned when they
// were created, so a driver can only learn them from the database it is
// connected to. Everything else — the types in pg_catalog — pgx already knows,
// and asking it to load them again would be a query per connection for nothing.
func (c *pkgContext) registerTypes(b *builder) {
	types := c.customTypes()

	b.blank()
	b.line("// RegisterTypes teaches a connection the PostgreSQL types this package's")
	b.line("// entities use that pgx does not know by default.")
	b.line("//")
	b.line("// Enums, domains and composites have OIDs assigned when they were created, so")
	b.line("// they are per-database facts a driver can only learn by asking. Wire it into")
	b.line("// a pool so every connection is taught once:")
	b.line("//")
	b.line("//\tcfg, err := pgxpool.ParseConfig(dsn)")
	b.line("//\tif err != nil {")
	b.line("//\t    return err")
	b.line("//\t}")
	b.line("//\tcfg.AfterConnect = %s.RegisterTypes", c.name)
	b.line("//\tpool, err := pgxpool.NewWithConfig(ctx, cfg)")
	b.line("//")
	if len(types) == 0 {
		b.line("// This package's entities use no such types, so this is a no-op kept for the")
		b.line("// sake of the pool setup above staying the same when one is added.")
		b.line("func RegisterTypes(ctx context.Context, conn *pgx.Conn) error { return nil }")
		return
	}
	b.line("// The order is a dependency order: an array's element type and a domain's base")
	b.line("// type are registered before the type built on them.")
	b.line("var ormCustomTypes = []string{")
	for _, t := range types {
		b.line("\t%s,", quote(t))
	}
	b.line("}")
	b.blank()
	b.line("func RegisterTypes(ctx context.Context, conn *pgx.Conn) error {")
	b.line("\tfor _, name := range ormCustomTypes {")
	b.line("\t\tt, err := conn.LoadType(ctx, name)")
	b.line("\t\tif err != nil {")
	b.line("\t\t\treturn fmt.Errorf(\"orm: loading PostgreSQL type %%s: %%w\", name, err)")
	b.line("\t\t}")
	b.line("\t\tconn.TypeMap().RegisterType(t)")
	b.line("\t}")
	b.line("\treturn nil")
	b.line("}")
	b.imports("fmt")
}

// customTypes lists the PostgreSQL types the package's mapped columns use that
// pgx has to be taught, in an order that registers a dependency before the type
// that needs it.
func (c *pkgContext) customTypes() []string {
	var out []string
	seen := make(map[string]bool)

	// The walk is over the entity list and its column list, both of which are
	// already in a fixed order, so the result is the same on every run without
	// anything being sorted afterwards.
	var add func(t *model.PGType)
	add = func(t *model.PGType) {
		if t == nil || !needsRegistration(t) {
			return
		}
		add(t.Elem)
		name := t.Schema + "." + t.Name
		if seen[name] {
			return
		}
		seen[name] = true
		out = append(out, name)
	}
	for _, em := range c.entities {
		for _, cm := range em.Cols {
			add(cm.Column.Type)
		}
	}
	return out
}

// needsRegistration reports whether pgx has to be told about a type.
//
// Only the kinds pgx can load are included. A base type has no per-database
// identity to learn — its OID is the same everywhere pg_catalog is — and asking
// pgx to load one fails, so including them would trade a working connection for
// a startup error.
func needsRegistration(t *model.PGType) bool {
	switch t.Kind {
	case model.PGEnum, model.PGDomain, model.PGComposite, model.PGRange, model.PGMultirange:
		return true
	case model.PGArray:
		return t.Elem != nil && needsRegistration(t.Elem)
	default:
		return false
	}
}

// builder accumulates one file's body and the imports it turned out to need.
type builder struct {
	pkg  string
	self string
	body strings.Builder
	imps map[string]bool
}

func newBuilder(pkg, selfPath string) *builder {
	return &builder{pkg: pkg, self: selfPath, imps: make(map[string]bool)}
}

// imports records packages the file references.
//
// A type declared in the package being generated into needs no import, and
// writing one would not compile. That case is not exotic: an entity's own enum
// type is the ordinary reason a column's value type names a package at all.
func (b *builder) imports(paths ...string) {
	for _, p := range paths {
		if p != "" && p != b.self {
			b.imps[p] = true
		}
	}
}

func (b *builder) line(format string, args ...any) {
	fmt.Fprintf(&b.body, format, args...)
	b.body.WriteByte('\n')
}

func (b *builder) blank() { b.body.WriteByte('\n') }

// file assembles the header, package clause, imports and body, then formats the
// result. Formatting last means the emitter never has to produce tidy
// whitespace, and a change to how it indents cannot show up as a diff.
func (b *builder) file(path string) (File, error) {
	var out bytes.Buffer
	out.WriteString(Header)
	out.WriteString("\n\npackage ")
	out.WriteString(b.pkg)
	out.WriteString("\n\n")

	if len(b.imps) > 0 {
		var std, ext []string
		for p := range b.imps {
			if isStdlib(p) {
				std = append(std, p)
			} else {
				ext = append(ext, p)
			}
		}
		slices.Sort(std)
		slices.Sort(ext)

		out.WriteString("import (\n")
		for _, p := range std {
			fmt.Fprintf(&out, "\t%s\n", quote(p))
		}
		if len(std) > 0 && len(ext) > 0 {
			out.WriteString("\n")
		}
		for _, p := range ext {
			fmt.Fprintf(&out, "\t%s\n", quote(p))
		}
		out.WriteString(")\n\n")
	}
	out.WriteString(b.body.String())

	formatted, err := format.Source(out.Bytes())
	if err != nil {
		return File{}, fmt.Errorf("generated code for %s does not parse: %w\n%s", filepath.Base(path), err, out.String())
	}
	return File{Path: path, Content: formatted}, nil
}

func quote(s string) string { return strconv.Quote(s) }

// columnFlags renders the write-side facts a column carries, omitting the ones
// that are false so the generated list stays readable.
func columnFlags(c *model.PGColumn) string {
	var b strings.Builder
	for _, f := range []struct {
		name string
		set  bool
	}{
		{"NotNull", !c.Nullable()},
		{"HasDefault", c.HasDefault},
		{"Identity", c.IsIdentity()},
		{"Generated", c.IsGenerated()},
	} {
		if f.set {
			fmt.Fprintf(&b, ", %s: true", f.name)
		}
	}
	return b.String()
}

// isStdlib reports whether an import path is in the standard library, so that
// generated imports group the way hand-written ones do. The standard library is
// exactly the set of paths whose first element is not a domain, which is the
// same rule goimports applies.
func isStdlib(path string) bool {
	first, _, _ := strings.Cut(path, "/")
	return !strings.Contains(first, ".")
}
